description:
Objective:
Fork a campaign from a checkpoint into a NEW Dolt branch plus an isolated SQLite
working copy. Add `DoltRepo.branch` and `CheckpointStore.forkFromCheckpoint`;
prove branch isolation (post-fork commits on main do not change the fork).

Files:
- Modify: `packages/core/src/persistence/checkpoint/doltRepo.ts`
- Modify: `packages/core/src/persistence/checkpoint/store.ts`
- Test:   `packages/core/test/checkpoint.fork.test.ts`

Steps:

1. Write the failing test `packages/core/test/checkpoint.fork.test.ts`:
```ts
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import { openDatabase } from '../src/persistence/db.js';
import { DoltRepo } from '../src/persistence/checkpoint/doltRepo.js';
import { CheckpointStore } from '../src/persistence/checkpoint/store.js';
import {
  serializeCampaign,
  canonicalize,
} from '../src/persistence/checkpoint/serialize.js';

const doltOk = DoltRepo.available();

describe.skipIf(!doltOk)('CheckpointStore.forkFromCheckpoint', () => {
  it('forks a checkpoint into an isolated branch + working copy', () => {
    const root = mkdtempSync(join(tmpdir(), 'lw-fk-'));
    const src = join(root, 'live.db');
    const db = openDatabase(src);
    db.exec('CREATE TABLE meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);');
    db.prepare('INSERT INTO meta(key, value) VALUES (?, ?)').run('hp', '5');
    db.close();

    const store = new CheckpointStore(join(root, 'dolt'), join(root, '.beads'));
    const c1 = store.checkpoint(src, 'cp1');

    const forkDb = join(root, 'fork.db');
    store.forkFromCheckpoint(c1, 'what-if', forkDb);
    const forkState = canonicalize(serializeCampaign(openDatabase(forkDb)));

    // Mutate the live db and checkpoint again on the main line.
    const db2 = openDatabase(src);
    db2.prepare('UPDATE meta SET value = ? WHERE key = ?').run('999', 'hp');
    db2.close();
    store.checkpoint(src, 'cp2-mainline');

    // Re-restore the fork branch tip: it must still equal the c1 state.
    const forkDb2 = join(root, 'fork2.db');
    store.forkFromCheckpoint(c1, 'what-if-2', forkDb2);
    const forkState2 = canonicalize(serializeCampaign(openDatabase(forkDb2)));

    expect(forkState).toContain('"hp"');
    expect(forkState).toContain('5');
    expect(forkState2).toBe(forkState);
    expect(forkState2).not.toContain('999');
  });
});
```

2. Run it to verify FAIL.
   Command: `npx vitest run packages/core/test/checkpoint.fork.test.ts`
   Expected: with dolt → FAIL (`forkFromCheckpoint` undefined); without dolt → skipped.

3. Add to `packages/core/src/persistence/checkpoint/doltRepo.ts` — a new method
   on `DoltRepo` (place after `readSnapshotAt`):
```ts
  branch(name: string, fromId: string): void {
    this.run(['branch', name, fromId]);
  }
```

4. Add to `CheckpointStore` in `packages/core/src/persistence/checkpoint/store.ts`:
```ts
  forkFromCheckpoint(
    checkpointId: string,
    branchName: string,
    destDbPath: string,
  ): string {
    this.repo.branch(branchName, checkpointId);
    return this.restoreToNewWorkingCopy(checkpointId, destDbPath);
  }
```

5. Run the test to verify PASS.
   Command: `npx vitest run packages/core/test/checkpoint.fork.test.ts`
   Expected: with dolt → 1 passed; without dolt → 1 skipped.

6. Run the full checkpoint suite to confirm no regression.
   Command: `npx vitest run packages/core/test/checkpoint.separation.test.ts packages/core/test/checkpoint.serialize.test.ts packages/core/test/checkpoint.doltRepo.test.ts packages/core/test/checkpoint.store.test.ts packages/core/test/checkpoint.restore.test.ts packages/core/test/checkpoint.fork.test.ts`
   Expected: separation + serialize always pass; dolt-gated suites pass with
   dolt, skip without.

7. Typecheck.
   Command: `npm run build`
   Expected: exit 0.

8. Commit.
   Command: `git add -A && git commit -m "feat(e8): fork campaign from checkpoint into new branch"`
